lib='''from collections import Counter

def counts(grid):
    """Frequency of each color in the grid, most common first."""
    return Counter(v for row in grid for v in row).most_common()

def has_square(grid, color, side=2):
    """True if the grid contains a side x side all-one-color square of that color."""
    h, w = len(grid), len(grid[0])
    return any(all(grid[i+di][j+dj] == color for di in range(side) for dj in range(side))
               for i in range(h - side + 1) for j in range(w - side + 1))

def block_and_bg(grid):
    """(block fill color, background color): the two frequent colors, block being the one forming a 2x2 square."""
    big = [c for c, n in counts(grid) if n >= len(grid) * len(grid[0]) * 0.1]
    block = next(c for c in big if has_square(grid, c))
    return block, next(c for c in big if c != block)

def marker_colors(grid):
    """Colors that are neither the block fill nor the background."""
    block, bg = block_and_bg(grid)
    return [c for c, _ in counts(grid) if c not in (block, bg)]

def marker_gridlines(grid):
    """Rows and columns (as index lists) that contain at least one marker cell."""
    marks = set(marker_colors(grid))
    gr = [i for i, row in enumerate(grid) if any(v in marks for v in row)]
    gc = [j for j in range(len(grid[0])) if any(row[j] in marks for row in grid)]
    return gr, gc, marks
